// Verified against the live API on 2026-07-20:
//   data[].revisedRequirements   (top level, NOT under a `requirements` object)
//   data[].locations[].iso3      with adminLevel 0 and isRegion false
// This endpoint carries no funding figure, so each plan needs a second call.
const plans = $input.first().json?.data;
if (!Array.isArray(plans)) {
  throw new Error('OCHA HPC returned an unexpected shape — no data array present.');
}

const items = [];
for (const plan of plans) {
  const requirements = Number(plan?.revisedRequirements ?? plan?.origRequirements);
  if (!Number.isFinite(requirements) || requirements <= 0) continue;

  // adminLevel 0 and not a region: country rows only, so regional plans do not
  // double-count their member states.
  const iso3s = (plan?.locations ?? [])
    .filter((l) => Number(l?.adminLevel) === 0 && l?.isRegion === false)
    .map((l) => String(l?.iso3 ?? '').toUpperCase())
    .filter((c) => c.length === 3);

  if (iso3s.length === 0) continue;

  items.push({ json: { planId: plan.id, requirements, iso3s } });
}

if (items.length === 0) {
  throw new Error('OCHA HPC returned no plans with usable requirements and country codes.');
}

return items;

// Verified shape: data.report1.fundingTotals.total
const observedAt = new Date().toISOString().slice(0, 10);
const byCountry = new Map();
const failedPlans = [];

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  // Pair each funding response back to the plan that produced it.
  const plan = $('Extract plans + countries').all()[i]?.json;
  if (!plan) continue;

  const funding = Number(items[i]?.json?.data?.report1?.fundingTotals?.total);

  for (const iso3 of plan.iso3s) {
    const acc = byCountry.get(iso3) ?? { requirements: 0, funding: 0, funded: false };
    // A multi-country plan's requirement is attributed in full to each country
    // it covers. Splitting it evenly would understate need in the country
    // actually hosting the response, and the API gives us no basis to weight it.
    acc.requirements += plan.requirements;
    if (Number.isFinite(funding)) {
      acc.funding += funding;
      acc.funded = true;
    }
    byCountry.set(iso3, acc);
  }

  if (!Number.isFinite(funding)) failedPlans.push(plan.planId);
}

if (failedPlans.length > 0) {
  console.warn('FTS: no funding figure for plans ' + failedPlans.join(', '));
}

if (byCountry.size === 0) {
  throw new Error('OCHA FTS produced no country-level rows.');
}

const observations = [];
for (const [iso3, acc] of byCountry) {
  observations.push({
    iso3,
    source: 'fts',
    metric: 'appeal_requirements_usd',
    value: acc.requirements,
    observedAt,
  });

  // Only emit a funded share when we actually retrieved funding. Emitting 0
  // for a failed lookup would read as 'completely unfunded' and wrongly
  // amplify that country's gap.
  if (acc.funded && acc.requirements > 0) {
    observations.push({
      iso3,
      source: 'fts',
      metric: 'appeal_funded_pct',
      // Clamped: appeals can be funded above 100%, which the API reports
      // faithfully but which fails the API's 0..1 validation.
      value: Math.min(1, Math.max(0, acc.funding / acc.requirements)),
      observedAt,
    });
  }
}

// Last workflow of the day — this is what fires scoring.
return [{ json: { source: 'fts', observations, triggerScoring: true } }];
